'use strict';
const API = '/api/teacher-growth';
const NAV = [
  ['overview','校长工作台','home','PRINCIPAL WORKSPACE'],
  ['profile','个人档案','user','TEACHER PORTFOLIO'],
  ['lessons','每课详情','book','CLASSROOM EVIDENCE'],
  ['support','培养与结对','team','SUPPORT & MENTORSHIP'],
  ['reports','阶段报告','chart','GROWTH REPORT'],
  ['appraisals','评价考核','check','APPRAISAL & DEVELOPMENT'],
  ['group','集团视图','school','GROUP PERSPECTIVE']
];
const STATUS = {achieved:'已达标',not_achieved:'未达标',undetermined:'待判断',pending:'待落实',completed:'已落实',active:'进行中',planned:'已计划',in_progress:'实践中',partial:'部分改善',open:'进行中',ended:'已结束',new:'待核实',verified:'已核实',supporting:'支持中',review:'待复评',closed:'已结案',not_connected:'待核验',improving:'改进已出现',persistent:'持续待支持',missing:'数据待补齐',unsupported:'支持待兑现',valid:'有效',missing_data:'缺失'};
const SCENARIOS={improving:'改进已出现',persistent:'持续待支持',missing:'数据待补齐',unsupported:'支持待兑现'};
const PERIODS={week:'本周', '4weeks':'近四周',semester:'本学期',year:'本年度'};
const ALERT_STEPS=['new','verified','supporting','review','closed'];
const ROLE={principal:'校长',teacher:'教师',mentor:'导师',group:'集团培养',grade_leader:'年级组'};
const state={data:null,actor:sessionStorage.getItem('houwai-teacher-actor')||'principal-001',page:'overview',teacher:null,profileTab:'growth',search:'',subject:'all',scenario:'all',lessonTeacher:'all',lessonStatus:'all',period:'4weeks',report:null,reportLoading:false,reportKey:'',overlay:null,importPreview:null,mobileNav:false,lab:null,labActor:null,labLoading:false,labError:''};
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(key,cls='')=>`<img class="icon ${cls}" src="assets/icons/${esc(key)}.svg" alt="" aria-hidden="true">`;
const date=v=>v?String(v).slice(0,10).replace(/-/g,'.'):'待约定';
const num=v=>Number.isFinite(Number(v))?Number(v):0;
const rate=v=>v===null||v===undefined?'—':`${Number(v).toFixed(Number(v)%1?1:0)}%`;
const tag=(text,kind='')=>`<span class="tag ${kind}">${esc(STATUS[text]||text)}</span>`;
const arrow='<span class="arrow" aria-hidden="true">↗</span>';
const teacherById=id=>(state.data?.teachers||[]).find(t=>t.id===id);
const teacher=()=>teacherById(state.teacher)||state.data?.teachers?.[0];
const own=id=>state.data?.actor?.teacher_id===id;
const principal=()=>state.data?.actor?.role==='principal';
const canGoal=id=>principal()||own(id);
const lessonTeacherName=l=>teacherById(l.teacher_id)?.name||l.teacher_id;
const teacherLessons=id=>(state.data?.lessons||[]).filter(l=>l.teacher_id===id).sort((a,b)=>String(b.date).localeCompare(String(a.date))||num(b.sequence)-num(a.sequence));
const related=(key,id)=>(state.data?.[key]||[]).filter(x=>x.teacher_id===id);
const activeMentorFor=id=>(state.data?.mentorships||[]).some(m=>m.teacher_id===id&&m.mentor_id===state.actor&&m.status==='active');
const canNote=m=>principal()||own(m.teacher_id)||m.mentor_id===state.actor;
function empty(title='暂无可见记录',text='切换教师或演示身份后，可查看其授权范围内的内容。'){return `<div class="empty">${icon('leaf')}<strong>${esc(title)}</strong>${esc(text)}</div>`;}
function statusKind(s){return ['achieved','completed','closed','improving'].includes(s)?'green':['not_achieved','persistent'].includes(s)?'red':['undetermined','missing','new','unsupported','pending'].includes(s)?'amber':'blue';}
function statusTag(s){return tag(s,statusKind(s));}
function avatar(t,cls=''){return `<img class="teacher-avatar ${cls}" src="assets/avatars/${esc(t.id)}.svg" alt="${esc(t.name.replace('',''))}的虚拟教师头像，非真人">`;}
function person(t,index=0){return `<div class="person-cell">${avatar(t,'table-avatar')}<div><strong>${esc(t.name)}</strong><small>${esc(t.subject||'教师')} · ${esc(t.department||t.campus||'香江路初中')}</small></div></div>`;}

function heading(title,desc,actions='',eyebrow='TEACHER GROWTH'){return `<header class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</header>`;}
function button(text,action,attrs='',primary=false,key=''){return `<button class="button${primary?' primary':''}" data-action="${action}" ${attrs}>${key?icon(key):''}${esc(text)}</button>`;}
function sourceLine(record){return `<div class="source-foot">依据 · ${esc(record.source||'本地演示样本')} · 来源编号 ${esc(record.source_id||record.id)}${record.metric_version?` · 口径 ${esc(record.metric_version)}`:''}<br>数据用于演示培养流程，校宝、讯飞与智慧作业生产系统尚未接入。</div>`;}
async function request(path,options={}){
  const headers={'X-Demo-Actor':state.actor,...(options.body?{'Content-Type':'application/json'}:{}),...options.headers};
  const response=await fetch(`${API}${path}`,{...options,headers});
  let payload;try{payload=await response.json();}catch{throw new Error('本地服务返回了无法读取的内容，请检查服务状态。');}
  if(!response.ok){const error=new Error(payload.error?.message||payload.message||`请求未完成（${response.status}）`);error.details=payload.error?.details;throw error;}
  return payload;
}
function post(path,body){return request(path,{method:'POST',body:JSON.stringify(body)});}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,error?6500:3500);}
function readRoute(){const parts=location.hash.replace(/^#\/?/,'').split('/');state.page=[...NAV.map(x=>x[0]),'sources'].includes(parts[0])?parts[0]:'overview';if(parts[1]&&teacherById(parts[1]))state.teacher=parts[1];}
function go(page,id){if(id)state.teacher=id;const h=`#${page}${id?`/${encodeURIComponent(id)}`:''}`;if(location.hash===h){state.page=page;render();if(page==='reports')loadReport();}else location.hash=h;}
async function refresh(){const requestedActor=state.actor,next=await request('/bootstrap');if(state.actor!==requestedActor)return;state.data=next;if(!teacherById(state.teacher))state.teacher=state.data.teachers?.[0]?.id||null;if(state.lessonTeacher!=='all'&&!teacherById(state.lessonTeacher))state.lessonTeacher='all';state.reportKey='';state.report=null;state.labActor=null;state.lab=null;state.labLoading=false;state.labError='';readRoute();render();if(state.page==='reports')await loadReport();}
function layout(content){const d=state.data;const title=({profile:'教师档案',sources:'数据与规则'})[state.page]||NAV.find(n=>n[0]===state.page)?.[1]||'集团总览';return `<div class="app-shell"><aside class="sidebar ${state.mobileNav?'open':''}" id="sidebar"><a class="brand" href="#overview" aria-label="厚外大教研与人才发展首页"><span class="brand-mark">厚</span><span><strong>厚外大教研<br>与人才发展</strong><small>RESEARCH & PEOPLE</small></span></a><div class="school-context"><p>${esc(d.actor?.campus||'厚外教育集团')}</p><small>共同定目标 · 持续有支持</small></div><div class="nav-caption">集团管理工作区</div><nav aria-label="主导航">${NAV.map(([page,label,key])=>`<button class="nav-item ${state.page===page?'active':''}" data-page="${page}" data-nav="${page}" aria-current="${state.page===page?'page':'false'}">${icon(key)}<span>${label}</span></button>`).join('')}</nav><div class="side-bottom"><button class="nav-item ${state.page==='sources'?'active':''}" data-page="sources" data-nav="sources">${icon('upload')}<span>数据与接入</span></button><div class="side-note v81-support-note"><strong>每一份成长，都有支持</strong><ol aria-label="培养与陪伴"><li><span>集团培养校长</span></li><li><span>校长培养教师</span></li><li><span>教师陪伴学生成长</span></li></ol></div></div></aside><div class="workspace"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="打开主导航">☰</button><div class="breadcrumb"><span class="crumb-root">厚外集团</span><span> / </span><strong>${esc(title)}</strong></div><div class="topbar-right"><span class="today">演示基准 · 2026年10月</span><div class="actor-control"><label for="actorSelect">演示身份</label><select id="actorSelect" class="actor-select" aria-label="切换演示身份">${d.actors.map(a=>`<option value="${esc(a.id)}" ${a.id===state.actor?'selected':''}>${esc(a.name)} · ${esc(ROLE[a.role]||a.role)}</option>`).join('')}</select><span class="actor-avatar" aria-hidden="true">${esc((d.actor.name||'师').slice(-1))}</span></div></div></header><div class="demo-notice"><span class="demo-dot"></span><span>本地演示 · 生产系统未接入 · 人事与薪酬联动待试点验证</span><a href="#sources">查看数据来源</a></div><main id="main" tabindex="-1">${content}<footer class="footer">厚外大教研与人才发展 · 以依据理解变化，以支持陪伴成长</footer></main></div></div>`;}
function render(){if(!state.data)return;const pages={overview,profile,lessons,support,reports,group,sources,appraisals};$('#app').innerHTML=layout(pages[state.page]());if(state.page==='sources'&&state.labActor!==state.actor)loadLab();if(typeof appraisalAfterRender==='function')appraisalAfterRender();}
function masteryCell(first){if(!first||first.status==='undetermined')return `<span class="mastery unknown">资料待补齐</span>`;return `<span class="mastery ${first.status==='achieved'?'good':'bad'}">${rate(first.percentage)}<small>首次</small></span>`;}
function metric(label,value,unit,foot,key,red=false){return `<div class="metric"><div class="metric-top">${label}${icon(key)}</div><div class="metric-value ${red?'red':''}">${esc(value)}${unit?`<small>${unit}</small>`:''}</div><div class="metric-foot">${foot}</div></div>`;}
function overview(){const d=state.data,ts=d.teachers||[],alerts=d.alerts.filter(a=>a.status!=='closed'),pending=d.supports.filter(s=>s.status!=='completed'),reviewGoals=d.goals.filter(g=>g.status!=='achieved'&&g.status!=='completed');
  const candidates=ts.slice().sort((a,b)=>{const order={persistent:0,unsupported:1,missing:2,improving:3};return order[a.scenario]-order[b.scenario];});
  const latestByTeacher=ts.map(t=>teacherLessons(t.id)[0]).filter(Boolean);
  return heading(d.actor.role==='teacher'?'我的成长工作台':'把培养，落到每一位教师','从一节课的依据，走向一个人的持续成长。',button('查看阶段报告','nav','data-page-target="reports"',false,'chart'), 'GROWTH BEGINS WITH UNDERSTANDING')+
  `<section class="hero"><div><div class="hero-kicker">校长逐人培养 · 首期探索</div><h2>看见变化，<br class="mobile-break">也看见背后的支持。</h2><p>课堂、作业与个人目标汇在一处。和教师共同理解问题，<br>安排具体支持，再回到实践中确认改变。</p><button class="text-link" data-page="support">查看培养与支持安排 ${arrow}</button></div><div class="hero-side">${icon('leaf')}<div><strong>${ts.length}<span>位教师 · 在授权范围内</span></strong><span>每一位都有自己的发展路径</span></div></div></section>`+
  `<section class="metric-strip" aria-label="当前培养概况">${metric('参与培养',ts.length,'位','按当前身份的授权范围','user')}${metric('正在关注',alerts.length,'项','核实 → 支持 → 复评','bell',alerts.length>0)}${metric('待兑现支持',pending.length,'项','学校与导师共同承担','hand')}${metric('发展目标',reviewGoals.length,'个','每周期聚焦一至两个目标','target')}</section>`+
  `<div class="overview-layout"><div><div class="section-heading"><h2>本期重点关注 <span class="count">${ts.length}</span></h2><button class="text-link" data-page="profile">全部教师档案 ${arrow}</button></div><section class="panel">${ts.length?`<div class="table-scroll"><table class="teacher-table"><thead><tr><th>教师</th><th class="hide-mobile">当前关注</th><th>最近课次</th><th class="hide-medium">待落实支持</th><th></th></tr></thead><tbody>${candidates.map((t,i)=>{const l=teacherLessons(t.id)[0],s=related('supports',t.id).filter(x=>x.status!=='completed');return `<tr><td><button data-teacher="${esc(t.id)}" aria-label="查看${esc(t.name)}个人档案">${person(t,i)}</button></td><td class="hide-mobile"><span class="focus-text">${esc(related('goals',t.id)[0]?.title||t.aspiration||'共同明确下一阶段目标')}</span><div style="margin-top:6px">${tag(SCENARIOS[t.scenario]||'待了解',statusKind(t.scenario))}</div></td><td>${l?`${masteryCell(l.first)}<small class="tiny">${date(l.date)}</small>`:'<span class="tiny">暂无课次</span>'}</td><td class="hide-medium">${s.length?tag(`${s.length}项待落实`,'amber'):tag('支持已落实','green')}</td><td><button class="text-link" data-teacher="${esc(t.id)}" aria-label="进入${esc(t.name)}档案">${arrow}</button></td></tr>`;}).join('')}</tbody></table></div><div class="table-foot"><span>关注安排可以并存与调整，不作为教师永久等级。</span><span>样本</span></div>`:empty('当前身份没有可见教师','校区与结对范围由本地服务分别校验。')}</section><section class="panel trend-panel"><div class="panel-head"><h2>把课堂变化与支持放在一起看</h2><small>最近课次 · 首次达标</small></div><div class="trend-layout"><div class="trend-legend"><h3>先看事实，再解释变化</h3><p>首次作业和复测分别呈现。资料缺失保持待判断，避免把未知当作未达标。</p><div class="legend-line"><span>首次表现</span><span>最近观察</span></div></div><div class="mini-chart-wrap"><div class="mini-chart">${latestByTeacher.length?latestByTeacher.map((l,i)=>`<div class="mini-bar-col"><span class="bar-label">${rate(l.first?.percentage)}</span><div class="bar" style="height:${Math.max(3,num(l.first?.percentage))*.72}px"></div><small>${esc(lessonTeacherName(l).replace('',''))}</small></div>`).join(''):'<span class="tiny">暂无可见课次</span>'}</div></div></div></section></div><aside class="overview-aside"><section><div class="section-heading"><h2>待兑现的支持</h2><button class="text-link" data-page="support">查看 ${arrow}</button></div><div class="panel"><div class="compact-list">${pending.slice(0,4).map(s=>`<article class="compact-item"><h3>${esc(s.title)}</h3><p>${esc(teacherById(s.teacher_id)?.name||'教师')} · ${esc(s.owner_name||'支持责任人待确认')}</p><div class="item-meta"><span>${date(s.due_date)} 前</span>${s.owner_id===state.actor?`<button class="text-link" data-action="complete-support" data-id="${esc(s.id)}">记录落实 ${arrow}</button>`:statusTag(s.status)}</div></article>`).join('')||empty('暂无待兑现支持','已落实的资源可在培养记录中回看。')}</div></div></section><section class="section-space"><div class="section-heading"><h2>需要先核实的信号</h2><span class="tiny">${alerts.length}项进行中</span></div><div class="panel"><div class="compact-list">${alerts.slice(0,3).map(a=>`<article class="compact-item"><div class="item-meta" style="margin:0 0 7px">${statusTag(a.status)}<span>${esc(teacherById(a.teacher_id)?.name||'教师')}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><div class="item-meta"><button class="text-link" data-action="alert-detail" data-id="${esc(a.id)}">查看跟进 ${arrow}</button><span>${date(a.due_date)}</span></div></article>`).join('')||empty('暂无进行中的预警','单一信号不会直接转为人事结论。')}</div></div></section></aside></div>`;
}
function teacherFilter(){return `<div class="filters"><div class="search"><label class="sr-only" for="teacherSearch">搜索教师姓名或学科</label><input id="teacherSearch" value="${esc(state.search)}" placeholder="搜索教师姓名、学科或发展方向" autocomplete="off"></div><label class="sr-only" for="subjectFilter">筛选学科</label><select class="filter-select" id="subjectFilter"><option value="all">全部学科</option>${[...new Set(state.data.teachers.map(t=>t.subject))].map(s=>`<option ${state.subject===s?'selected':''}>${esc(s)}</option>`).join('')}</select><label class="sr-only" for="scenarioFilter">筛选关注情况</label><select class="filter-select" id="scenarioFilter"><option value="all">全部关注情况</option>${Object.entries(SCENARIOS).map(([k,v])=>`<option value="${k}" ${state.scenario===k?'selected':''}>${v}</option>`).join('')}</select></div>`;}
function filteredTeachers(){return state.data.teachers.filter(t=>(state.subject==='all'||t.subject===state.subject)&&(state.scenario==='all'||t.scenario===state.scenario)&&`${t.name}${t.subject}${t.aspiration}`.toLowerCase().includes(state.search.toLowerCase()));}
function profile(){const list=filteredTeachers(),t=list.find(x=>x.id===state.teacher)||list[0];if(t)state.teacher=t.id;return heading('教师个人档案','个人经历与课堂记录汇在一处，培养重点清楚可见。','', 'TEACHER PORTFOLIO')+teacherFilter()+`<div class="directory"><aside class="teacher-directory" aria-label="教师列表"><div class="directory-caption">授权教师 · ${list.length}位</div>${list.map((p,i)=>`<button class="teacher-option ${p.id===t?.id?'active':''}" data-select-teacher="${esc(p.id)}" aria-pressed="${p.id===t?.id}">${avatar(p,'directory-avatar')}<span><strong>${esc(p.name)}</strong><small>${esc(p.subject)} · ${SCENARIOS[p.scenario]||'培养中'}</small></span></button>`).join('')||empty('没有匹配的教师','调整搜索词或筛选条件。')}</aside><div>${t?profileDetail(t):empty()}</div></div>`;}
function profileDetail(t){const tabs=[['growth','成长概览'],['classroom','课堂与学情'],['records','履历与荣誉'],...(state.data.actor.role!=='mentor'?[['appraisal','评价考核']]:[]),['hr','基础档案']];const facts=[['校区 / 学部',`${t.campus||'授权校区'} · ${t.department||'授权学部'}`],['任教学科',t.subject],...(t.years!=null?[['教龄',`${t.years}年`]]:[]),...(t.education?[['学历',t.education]]:[])];return `<section class="profile-hero"><div class="profile-head"><div class="profile-portrait">${avatar(t,'profile-avatar')}<span>虚拟形象</span></div><div class="profile-name"><div class="profile-name-line"><h1>${esc(t.name)}</h1>${tag(t.employment||'授权培养视图','blue')}</div><p>${esc(t.employee_no?`工号 ${t.employee_no}`:'仅查看授权培养信息')} · 长期成长档案</p><div class="identity-facts">${facts.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div></div><div class="profile-side"><strong>${teacherLessons(t.id).length}</strong>节课堂记录<br>首次与复测分别记录</div></div><nav class="profile-tabbar" aria-label="个人档案内容">${tabs.map(([k,v])=>`<button class="${state.profileTab===k?'active':''}" data-profile-tab="${k}" aria-pressed="${state.profileTab===k}">${v}</button>`).join('')}</nav></section>${state.profileTab==='growth'?profileGrowth(t):state.profileTab==='classroom'?profileClassroom(t):state.profileTab==='records'?profileRecords(t):state.profileTab==='appraisal'?appraisalWorkspace(t,true):profileHr(t)}`;}
function profileFocus(t){const goals=related('goals',t.id),goal=goals.find(g=>!['achieved','completed'].includes(g.status))||goals[0],ls=teacherLessons(t.id),latest=ls[0],baseline=ls.slice().reverse().find(l=>l.first?.status!=='undetermined'),supports=related('supports',t.id),pending=supports.filter(s=>s.status!=='completed'),alerts=related('alerts',t.id).filter(a=>a.status!=='closed'),next=pending[0]||alerts[0]||goal;return `<section class="profile-focus" aria-label="本期培养重点"><article><div class="focus-label">当前发展目标${icon('target')}</div><h3>${esc(goal?.title||'共同明确一个阶段目标')}</h3><p>${goal?`约定 ${date(goal.due_date)} 复评`:'先了解本人意愿与支持需要'}</p><button class="text-link" data-page="support">查看目标与实践 ↗</button></article><article><div class="focus-label">首次作业90/90观察${icon('book')}</div><div class="focus-numbers">${latest?.first?.status==='undetermined'?'<strong>待判断</strong>':`<span>${rate(baseline?.first?.percentage)}</span><i>→</i><strong>${rate(latest?.first?.percentage)}</strong>`}</div><p>起点 → 最近课次${latest?` · ${date(latest.date)}`:''}</p>${latest?`<button class="text-link" data-lesson="${esc(latest.id)}">回看课堂与复测 ↗</button>`:'<span class="tiny">暂无课次依据</span>'}</article><article><div class="focus-label">待兑现的培养支持${icon('hand')}</div><div class="focus-numbers"><strong>${pending.length}</strong><span class="focus-unit">项待落实</span></div><p>${supports.length-pending.length} / ${supports.length}项学校或导师支持已落实</p><button class="text-link" data-page="support">查看责任与落实依据 ↗</button></article><article><div class="focus-label">校长下一步${icon('calendar')}</div><h3>${pending.length?'兑现支持并确认实践安排':alerts.length?'核实信号，安排支持与复查':'共同回看目标与课堂变化'}</h3><p>${next?`${date(next.due_date)}前跟进`:'在下一次成长面谈中共同约定'}</p><button class="text-link" data-page="support">打开培养安排 ↗</button></article></section>`;}

function profileGrowth(t){return `${profileFocus(t)}<div class="profile-columns"><div><section class="panel"><div class="panel-head"><h2>发展意愿与优势</h2>${own(t.id)?'<button class="text-link" data-action="edit-aspiration">更新我的方向 ↗</button>':''}</div><div class="panel-body"><p class="aspiration">${esc(t.aspiration||'在共同面谈中了解教师的发展意愿。')}</p><div class="chips">${(t.strengths||[]).map(s=>tag(s,'green')).join('')}</div><p class="tiny">本人意愿与观察依据分别记录，阶段判断随实践更新。</p></div></section><section class="panel"><div class="panel-head"><h2>本期发展目标</h2>${canGoal(t.id)?'<button class="text-link" data-action="add-goal">共同定目标 ↗</button>':''}</div><div class="panel-body">${goalList(t.id)}</div></section><section class="panel"><div class="panel-head"><h2>正式反馈与本人回应</h2><small>保留原文及回应</small></div><div class="panel-body">${feedbackList(t.id)}</div></section></div><aside class="profile-aside"><section class="panel"><div class="panel-head"><h2>能力观察</h2><small>不汇成总分</small></div><div class="panel-body">${(t.dimensions||[]).map(v=>`<div class="dimension"><h3>${esc(v.name)}</h3><p>${esc(v.description)}</p><span class="evidence-count">${v.evidence_ids?.length||0}条关联依据</span></div>`).join('')||'<p class="tiny">能力观察仍待补充。</p>'}</div></section><section class="panel"><div class="panel-head"><h2>成长时间线</h2></div><div class="panel-body">${timeline(t.timeline||[])}</div></section></aside></div>`;}
function timeline(items){return items.length?`<ol class="timeline">${items.slice().reverse().slice(0,8).map(v=>`<li><small>${date(v.date)}</small><strong>${esc(v.title||v.role)}</strong>${v.detail?`<p>${esc(v.detail)}</p>`:''}</li>`).join('')}</ol>`:empty('时间线待补充','在每次实践和复评中逐步积累。');}
function goalList(id){const goals=related('goals',id);return goals.length?goals.map(g=>`<article class="goal-card"><div class="goal-heading"><h3>${esc(g.title)}</h3>${statusTag(g.status)}</div><div class="goal-baseline">当前起点：${esc(g.baseline||'待共同确认')}</div><p>预期变化：${esc(g.target)}</p><div class="action-row"><span class="tiny">复评 ${date(g.due_date)}</span>${principal()?`<button class="text-link" data-action="review-goal" data-id="${esc(g.id)}">记录阶段复评 ↗</button><button class="text-link muted" data-action="add-support" data-goal-id="${esc(g.id)}" data-teacher-id="${esc(id)}">安排支持 ↗</button>`:''}</div>${(g.reviews||[]).map(r=>`<div class="response"><strong>${date(r.created_at||r.date)} · ${esc(STATUS[r.conclusion]||r.conclusion||'阶段复评')}</strong>${esc(r.text)}</div>`).join('')}</article>`).join(''):empty('先共同确定一个目标','聚焦一至两个可以在实践中观察的变化。');}
function feedbackList(id){const list=related('feedback',id);return list.length?list.map(f=>`<article class="feedback-item"><p>${esc(f.text)}</p><div class="feedback-meta">${esc(f.author_name||'培养负责人')} · ${date(f.created_at)} · ${f.evidence_ids?.length||0}条依据</div>${f.lesson_id?`<button class="text-link" data-lesson="${esc(f.lesson_id)}">查看对应课次 ↗</button>`:''}${(f.responses||[]).map(r=>`<div class="response"><strong>教师本人回应 · ${date(r.created_at)}</strong>${esc(r.text)}</div>`).join('')}${own(id)?`<div class="action-row"><button class="text-link" data-action="respond-feedback" data-id="${esc(f.id)}">回应正式反馈 ↗</button></div>`:''}</article>`).join(''):empty('暂无正式反馈','正式反馈将记录依据，并允许教师补充回应。');}
function profileClassroom(t){return `<section class="panel"><div class="panel-head"><h2>任教关系与课堂记录</h2><button class="text-link" data-action="teacher-lessons" data-id="${esc(t.id)}">查看全部课次 ↗</button></div><div class="panel-body"><div class="chips">${(t.assignments||[]).map(a=>tag(`${a.class_name} · ${a.subject||t.subject}`)).join('')}</div><p class="tiny">按课次日期核对任教期间，首次达标与复测结果分别保存。</p></div>${lessonTable(teacherLessons(t.id))}</section>`;}
function profileRecords(t){return `<div class="hr-grid"><section class="panel"><div class="panel-head"><h2>竞赛与专业荣誉</h2><small>长期积累</small></div><div class="panel-body honor-list">${(t.honors||[]).map(h=>`<article class="honor">${icon('trophy')}<div><h3>${esc(h.title)}</h3><p>${date(h.date)} · ${esc(h.level)}</p></div></article>`).join('')||empty('暂无授权荣誉记录')}</div></section><section class="panel no-margin"><div class="panel-head"><h2>学习与教研</h2><small>关注实践转化</small></div><div class="panel-body">${(t.training||[]).map(h=>`<article class="honor">${icon('graduation')}<div><h3>${esc(h.title)}</h3><p>${date(h.date)}</p><p>${esc(h.reflection||'实践转化记录待补充')}</p></div></article>`).join('')||empty('暂无授权学习记录')}</div></section></div><section class="panel section-space"><div class="panel-head"><h2>任职经历</h2></div><div class="panel-body">${(t.experience||[]).map(x=>`<div class="archive-item"><span>${esc(x.period)}</span><strong>${esc(x.role)}</strong></div>`).join('')||'<p class="tiny">当前身份未获授权查看任职经历。</p>'}</div></section>`;}
function profileHr(t){const hasFacts=t.employee_no||t.education||t.qualifications?.length;return `<section class="panel"><div class="panel-head"><h2>基础人事信息</h2><small>首版事实字段只读</small></div><div class="panel-body">${hasFacts?`<dl class="facts"><dt>演示工号</dt><dd>${esc(t.employee_no||'—')}</dd><dt>学校与学部</dt><dd>${esc(t.campus||'—')} · ${esc(t.department||'—')}</dd><dt>任教学科</dt><dd>${esc(t.subject)}</dd><dt>教龄</dt><dd>${esc(t.years||0)}年</dd><dt>学历</dt><dd>${esc(t.education||'—')}</dd><dt>在职情况</dt><dd>${esc(t.employment||'—')}</dd><dt>资格资质</dt><dd>${(t.qualifications||[]).map(esc).join('、')||'—'}</dd></dl>`:empty('当前身份无基础人事明细权限','导师与集团培养角色按授权查看培养信息。')}<div class="quiet-note">人事事实以经核验的档案主源为准。薪酬、退出评议和私人人事意见另行授权，本演示不提供相应明细。</div><h3 style="margin:25px 0 14px">任教期间</h3>${(t.assignments||[]).map(a=>`<div class="archive-item"><span>${esc(a.class_name)} · ${esc(a.subject||t.subject)}</span><span>${date(a.valid_from)} — ${a.valid_to?date(a.valid_to):'至今'}</span></div>`).join('')}</div></section>`;}
function lessonTable(items){return items.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>课次与主题</th><th>班级 / 日期</th><th>首次达标</th><th>复测</th><th></th></tr></thead><tbody>${items.map(l=>`<tr><td><button class="lesson-title" data-lesson="${esc(l.id)}">${esc(l.title)}<small>${esc(lessonTeacherName(l))} · 第${esc(l.sequence)}课</small></button></td><td><span class="nowrap">${esc(l.class_name)}</span><br><span class="tiny">${date(l.date)}</span></td><td>${masteryCell(l.first)}</td><td>${l.retest?`<span class="mastery ${l.retest.status==='achieved'?'good':'bad'}">${rate(l.retest.percentage)}</span><small class="tiny">单独记录</small>`:'<span class="tiny">尚无复测</span>'}</td><td><button class="text-link" data-lesson="${esc(l.id)}" aria-label="查看${esc(l.title)}课次详情">${arrow}</button></td></tr>`).join('')}</tbody></table></div>`:empty('暂无匹配课次','调整教师和达标状态筛选，或查看数据接入情况。');}
function lessons(){let list=state.data.lessons.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))||num(b.sequence)-num(a.sequence));if(state.lessonTeacher!=='all')list=list.filter(l=>l.teacher_id===state.lessonTeacher);if(state.lessonStatus!=='all')list=list.filter(l=>l.first?.status===state.lessonStatus);return heading('每一节课，都能找到改进的依据','课堂观察、首次作业与复测结果分开看，回到具体依据。','', 'CLASSROOM EVIDENCE')+`<div class="filters"><label class="sr-only" for="lessonTeacherFilter">选择任教教师</label><select class="filter-select" id="lessonTeacherFilter"><option value="all">全部授权教师</option>${state.data.teachers.map(t=>`<option value="${esc(t.id)}" ${state.lessonTeacher===t.id?'selected':''}>${esc(t.name)} · ${esc(t.subject)}</option>`).join('')}</select><label class="sr-only" for="lessonStatusFilter">筛选首次作业达标状态</label><select class="filter-select" id="lessonStatusFilter"><option value="all">全部首次达标状态</option>${['achieved','not_achieved','undetermined'].map(s=>`<option value="${s}" ${state.lessonStatus===s?'selected':''}>${STATUS[s]}</option>`).join('')}</select><span class="filter-result">${list.length}节授权课次</span></div><section class="panel">${lessonTable(list)}</section><div class="quiet-note">课堂达标按约定的“90%学生、90%正确率”精确计算；资料不齐保持待判断。复测用于观察支持后的变化，不覆盖首次结果。所有转写与逐题数据均为样本。</div>`;}
function support(){const t=teacher();return heading('有目标，更要有兑现的支持','把导师、时间与资源安排具体，让下一次复评有事可回看。',principal()&&t?button('安排支持','add-support',`data-teacher-id="${esc(t.id)}"`,true,'hand'):'','SUPPORT & MENTORSHIP')+teacherChooser('supportTeacher')+(t?`<div class="workspace-grid"><div><div class="section-heading"><h2>发展目标</h2>${canGoal(t.id)?'<button class="text-link" data-action="add-goal">新增目标 ↗</button>':''}</div><section class="panel"><div class="panel-body">${goalList(t.id)}</div></section><div class="section-heading section-space"><h2>学校与导师的支持</h2><span class="tiny">责任人与完成依据</span></div><div class="card-grid">${related('supports',t.id).map(s=>supportCard(s)).join('')||`<section class="panel">${empty('暂无支持安排','先共同确定目标，再落实具体支持。')}</section>`}</div><div class="section-heading section-space"><h2>同伴结对与辅导</h2>${principal()?'<button class="text-link" data-action="add-mentorship">安排结对 ↗</button>':''}</div><section class="panel"><div class="panel-body">${mentorshipList(t.id)}</div></section></div><div><div class="section-heading"><h2>关注信号与跟进</h2><span class="tiny">${related('alerts',t.id).length}项</span></div><section class="panel"><div class="panel-body">${related('alerts',t.id).map(a=>alertCard(a)).join('')||empty('暂无关注信号','支持的需要也可以在面谈中主动提出。')}</div></section><div class="quiet-note">同一位教师可以同时有优势和困难。关注安排用来决定下一步支持，校长未兑现的承诺也一起复盘。</div></div></div>`:empty());}
function teacherChooser(id){return `<div class="filters"><label class="sr-only" for="${id}">选择教师</label><select class="filter-select" id="${id}">${state.data.teachers.map(t=>`<option value="${esc(t.id)}" ${state.teacher===t.id?'selected':''}>${esc(t.name)} · ${esc(t.subject)}</option>`).join('')}</select><span class="tiny">${esc(teacher()?.campus||'授权范围')} · ${esc(ROLE[state.data.actor.role]||'培养视图')}</span></div>`;}
function supportCard(s){return `<article class="support-card"><div class="card-top">${icon('hand')}${statusTag(s.status)}</div><h3>${esc(s.title)}</h3><p>${esc(related('goals',s.teacher_id).find(g=>g.id===s.goal_id)?.title||'关联培养目标')}</p><div class="owner-line">${esc(s.owner_name||'支持责任人')} · ${date(s.due_date)}前</div>${s.evidence?`<p style="margin-top:10px">落实依据：${esc(s.evidence)}</p>`:''}${s.status!=='completed'&&s.owner_id===state.actor?`<div class="action-row"><button class="text-link" data-action="complete-support" data-id="${esc(s.id)}">记录支持落实 ↗</button></div>`:''}</article>`;}
function mentorshipList(id){const list=related('mentorships',id);return list.length?list.map(m=>`<article class="mentor-pair"><div class="pair-people"><div><strong>${esc(teacherById(id)?.name)}</strong><small>共同实践</small></div><span>⇄</span><div><strong>${esc(m.mentor_name||state.data.mentors.find(x=>x.id===m.mentor_id)?.name||'导师')}</strong><small>日常辅导</small></div></div><p>${esc(m.reason)}</p><p style="margin-top:7px">双方意愿已确认 · 截止 ${date(m.end_date)} · ${esc(STATUS[m.status]||m.status)}</p>${(m.notes||[]).map(n=>`<div class="pair-note">${esc(n.text)}<br><span class="tiny">${esc(n.author_name||'参与人')} · ${date(n.created_at)}</span></div>`).join('')}${canNote(m)&&m.status==='active'?`<div class="action-row"><button class="text-link" data-action="mentor-note" data-id="${esc(m.id)}">记录辅导与尝试 ↗</button></div>`:''}</article>`).join(''):empty('尚未建立结对','结合目标、导师专长与双方意愿确定支持关系。');}
function alertSteps(a){const pos=ALERT_STEPS.indexOf(a.status);return `<div class="alert-steps" aria-label="跟进状态：${esc(STATUS[a.status]||a.status)}">${ALERT_STEPS.map((k,i)=>`<span class="alert-step ${i<=pos?'done':''} ${i===pos?'current':''}">${STATUS[k]}</span>`).join('')}</div>`;}
function alertCard(a){return `<article class="alert-item"><div class="goal-heading"><h3>${esc(a.title)}</h3>${statusTag(a.status)}</div><p>${esc(a.description)}</p>${alertSteps(a)}<p>${esc(a.owner_name||'负责人待确认')} · ${date(a.due_date)}复查</p><div class="action-row"><button class="text-link" data-action="alert-detail" data-id="${esc(a.id)}">查看过程 ${arrow}</button>${principal()&&a.status!=='closed'?`<button class="text-link" data-action="advance-alert" data-id="${esc(a.id)}">${a.status==='new'?'核实信号':a.status==='verified'?'记录支持':a.status==='supporting'?'发起复评':'记录结案'} ${arrow}</button>`:''}</div></article>`;}
function reports(){const t=teacher();return heading('回看一段实践，确定下一步支持','每次报告保留时间范围、依据和资料局限，不用一个总分概括教师。','', 'GROWTH REPORT')+`<div class="report-selector"><label class="sr-only" for="reportTeacher">选择报告教师</label><select class="filter-select" id="reportTeacher">${state.data.teachers.map(x=>`<option value="${esc(x.id)}" ${state.teacher===x.id?'selected':''}>${esc(x.name)} · ${esc(x.subject)}</option>`).join('')}</select><div class="period-tabs" aria-label="报告周期">${Object.entries(PERIODS).map(([k,v])=>`<button class="${state.period===k?'active':''}" data-period="${k}" aria-pressed="${state.period===k}">${v}</button>`).join('')}</div></div><div id="reportContent">${!t?empty():state.reportLoading?'<div class="panel loading">正在核对本周期依据…</div>':state.report?reportDetail(state.report,t):'<div class="panel loading">正在载入阶段报告…</div>'}</div>`;}
async function loadReport(){const t=teacher();if(!t)return;const key=`${state.actor}/${t.id}/${state.period}`;if(state.reportKey===key&&state.report)return;state.reportLoading=true;state.reportKey=key;if(state.page==='reports')render();try{const r=await request(`/reports/${encodeURIComponent(t.id)}?period=${state.period}`);if(state.reportKey!==key)return;state.report=r;state.reportLoading=false;if(state.page==='reports')render();}catch(e){state.reportLoading=false;if(state.page==='reports'&&$('#reportContent'))$('#reportContent').innerHTML=`<div class="error-panel"><h2>报告暂未载入</h2><p>${esc(e.message)}</p>${button('重新载入','retry-report')}</div>`;}}
function reportDetail(r,t,archived=false){const c=r.current||{},p=r.previous||{},series=r.series||[];return `<section class="panel"><div class="report-heading"><div><div class="eyebrow">阶段培养回顾</div><h2>${esc(t.name)} · ${esc(r.label||PERIODS[state.period])}</h2><p>${date(r.start)} — ${date(r.end)}<br>对照上一周期 ${date(r.previous_start)} — ${date(r.previous_end)}</p></div>${principal()&&!archived?button('归档本期报告','archive-report','',false,'bookmark'):tag(archived?'归档快照':'授权只读','blue')}</div><div class="report-body"><div class="report-metrics"><div class="report-metric"><small>有效课次达标率</small><strong>${rate(c.mastery_rate)}</strong><span>上一周期 ${rate(p.mastery_rate)}</span></div><div class="report-metric"><small>可见课堂记录</small><strong>${esc(c.lessons||0)}<small style="display:inline"> 节</small></strong><span>有效 ${esc(c.valid_lessons||0)}节 · 待判断 ${esc(c.unknown_lessons||0)}节</span></div><div class="report-metric"><small>支持已落实</small><strong>${esc(r.support?.completed||0)}<small style="display:inline"> / ${esc(r.support?.total||0)}</small></strong><span>逾期 ${esc(r.support?.overdue||0)}项</span></div><div class="report-metric"><small>阶段复评记录</small><strong>${esc(r.goal_reviews?.length||0)}<small style="display:inline"> 条</small></strong><span>与原目标、行动依据对应</span></div></div>${classroomComparison(r,archived)}<div class="section-heading"><h2>课堂记录的阶段变化</h2><span class="tiny">首次达标 · 有效课次口径</span></div><div class="report-chart">${series.length?series.map(s=>`<div class="mini-bar-col"><span class="bar-label">${rate(s.rate)}</span><div class="bar" style="height:${s.rate==null?3:Math.max(3,num(s.rate)*1.25)}px" title="${esc(s.label)}，达标率${rate(s.rate)}，覆盖率${rate(s.coverage)}"></div><small>${esc(s.label)}</small></div>`).join(''):'<p class="tiny">当前周期没有可比较的课堂序列。</p>'}</div><p class="tiny">达标率为有效课次中已达标课次占比。资料不齐的课次单列，复测不替代首次结果。</p>${retestComparison(r,archived)}<div class="report-columns"><div><h3>本期观察</h3><ul class="observation-list">${(r.observations||[]).map(x=>`<li>${esc(typeof x==='object'?x.text||x.description||JSON.stringify(x):x)}</li>`).join('')||'<li>当前依据仍待结合面谈解释。</li>'}</ul></div><div><h3>解释这些变化前，还要知道</h3><ul class="observation-list">${(r.limitations||[]).map(x=>`<li>${esc(typeof x==='object'?x.text||JSON.stringify(x):x)}</li>`).join('')||'<li>结合任教期间、任务难度、班级起点及数据覆盖率。</li>'}</ul></div></div>${r.goal_reviews?.length?`<div class="section-space"><h3 style="margin-bottom:14px">目标复评与下一步</h3>${r.goal_reviews.map(v=>`<div class="response"><strong>${esc(v.title||v.goal_title||STATUS[v.conclusion]||'目标复评')} · ${date(v.created_at||v.date)}</strong>${esc(v.text||v.conclusion||'')}</div>`).join('')}</div>`:''}<p class="report-evidence">关联依据：${(r.evidence_ids||[]).map(esc).join(' · ')||'待补充'}<br>样本，仅用于验证培养流程；本报告不自动改变教师薪酬、职称或岗位。</p></div></section><section class="panel section-space"><div class="panel-head"><h2>已归档的阶段快照</h2><small>归档后保留原版</small></div><div class="panel-body">${(r.archived||[]).map(a=>`<div class="archive-item"><span>${esc(a.label||PERIODS[a.period]||'阶段报告')} · ${date(a.created_at||a.archived_at)}</span><span>快照 ${esc(a.id)}</span>${state.data.actor.role!=='mentor'?`<button class="text-link" data-action="view-archive" data-id="${esc(a.id)}" data-teacher-id="${esc(t.id)}">查看原版 ↗</button>`:''}</div>`).join('')||'<p class="tiny">尚未归档。校长可在完成本期复盘后保存报告快照。</p>'}</div></section>`;}
function group(){const d=state.data,ts=d.teachers,ss=d.supports,completed=ss.filter(s=>s.status==='completed').length,ms=d.mentorships.filter(m=>m.status==='active');return heading('发现人才，也发现组织需要改进的地方','把教师的发展机会、共性困难与校长支持责任放在同一个视野。','', 'GROUP PERSPECTIVE')+`<div class="group-intro"><h2>从培养过程，理解学校的培养能力。</h2><p>关注校长是否了解教师、共同定目标、提供恰当资源并持续复盘；同时核对接手基础与资源条件。当前授权范围内 ${ts.length}位教师，未形成跨校区人才排名。</p></div><section class="metric-strip">${metric('授权教师',ts.length,'位','集团与校区查看范围分别裁剪','user')}${metric('已落实支持',completed,'项',`共${ss.length}项学校与导师承诺`,'hand')}${metric('有效结对',ms.length,'组','以双方意愿和容量为依据','team')}${metric('待判断课次',d.lessons.filter(l=>l.first?.status==='undetermined').length,'节','信息缺口进入补齐清单','note')}</section><div class="section-heading"><h2>教师发展与支持全景</h2><span class="tiny">动态安排 · 非绩效排名</span></div><section class="panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>教师</th><th>发展意愿</th><th>培养目标</th><th>学校支持</th><th>结对</th><th></th></tr></thead><tbody>${ts.map((t,i)=>{const s=related('supports',t.id),m=related('mentorships',t.id);return `<tr><td><button data-teacher="${esc(t.id)}">${person(t,i)}</button></td><td><span class="focus-text">${esc(t.aspiration)}</span></td><td>${related('goals',t.id).length}个目标<br><span class="tiny">${SCENARIOS[t.scenario]||'待了解'}</span></td><td>${s.filter(x=>x.status==='completed').length} / ${s.length} 已落实</td><td>${m.filter(x=>x.status==='active').length}组有效</td><td><button class="text-link" data-teacher="${esc(t.id)}" aria-label="查看${esc(t.name)}">${arrow}</button></td></tr>`;}).join('')||'<tr><td colspan="6">当前身份没有授权教师记录。</td></tr>'}</tbody></table></div></section><div class="group-matrix"><article class="matrix-cell">${icon('leaf')}<strong>${ts.filter(t=>t.scenario==='improving').length}位</strong><h3>可继续验证的改进经验</h3><p>观察方法在哪些情境有效，经本人同意后形成可分享的课例与同伴支持。</p></article><article class="matrix-cell">${icon('hand')}<strong>${ss.filter(s=>s.status!=='completed').length}项</strong><h3>组织尚需兑现的支持</h3><p>先核对时间、导师和资源有没有到位，再解释教师目标未改善的原因。</p></article><article class="matrix-cell">${icon('team')}<strong>${d.mentors.filter(m=>m.willing&&num(m.active_count)<num(m.capacity)).length}位</strong><h3>还有容量的导师</h3><p>匹配具体目标与专长，确认双方意愿；示范与带教也需要时间保障。</p></article></div><section class="panel"><div class="panel-head"><h2>校长培养责任的回看</h2><small>观察过程与结果，不按填报量排序</small></div><div class="panel-body"><div class="report-columns no-margin"><div><h3>逐人培养有没有发生</h3><ul class="observation-list"><li>${d.goals.length}个授权发展目标，关联具体教师与复评时间。</li><li>${ss.length}项支持承诺，其中${completed}项已提供落实依据。</li><li>${ms.length}组有效结对，导师安排与教师意愿共同确认。</li></ul></div><div><h3>集团下一步可以提供什么</h3><ul class="observation-list"><li>对共性难点安排跨校共备、观课与案例校准。</li><li>对未兑现支持核实责任、课务冲突与资源缺口。</li><li>和校长共同确定管理改进目标，下一周期再次复盘。</li></ul></div></div></div></section><div class="quiet-note">集团培养角色为授权只读视图，不展示他人私人反思及薪酬明细。人才名单与人事评议需采用另行确认的制度和授权。</div>`;}
function sources(){const d=state.data;return heading('数据接入，先把来源与口径核清楚','先用经过校验的文件跑通培养流程，再逐项连接正式系统。',principal()?button('导入作业样本','import','',true,'upload'):'','DATA & CONNECTIONS')+`<section class="panel"><div class="panel-head"><h2>来源核验清单</h2><small>生产系统均未接入</small></div><div class="panel-body">${d.sources.map((s,i)=>`<article class="source-row">${icon(['user','book','note','chart'][i%4])}<div><h3>${esc(s.name)}</h3><p>${esc(s.note)}</p><small>${esc(s.mode||'待核验导出或接口')} · 最近同步：未发生</small></div>${tag('待核验','amber')}</article>`).join('')}</div></section><div class="workspace-grid section-space"><section class="panel"><div class="panel-head"><h2>经校验的作业文件交换</h2>${principal()?'<button class="text-link" data-action="import">打开导入 ↗</button>':''}</div><div class="panel-body"><p class="tiny">示例CSV仅接受既有课次与SIM学生。导入分为预览与确认两步，同批次重复确认不会重复写入；字段错误整批拒绝。</p>${principal()?`<div class="action-row"><button class="button small" data-action="download-template">${icon('file')}下载CSV模板</button></div>`:''}<div class="quiet-note">首次作业与复测分列；缺失、无效或缺席均标为未知，避免被当成错误。真实供应商的字段映射、数据权限与更新频率需另行核验。</div></div></section><section class="panel no-margin"><div class="panel-head"><h2>当前访问边界</h2><small>由服务端逐项检查</small></div><div class="panel-body"><dl class="facts"><dt>当前身份</dt><dd>${esc(d.actor.name)} · ${ROLE[d.actor.role]||d.actor.role}</dd><dt>可见教师</dt><dd>${d.teachers.length}位</dd><dt>可见课次</dt><dd>${d.lessons.length}节</dd><dt>反思分享</dt><dd>本人默认私有，可分别分享给校长、导师与集团。</dd><dt>人事应用</dt><dd>试点验证后再形成正式联动制度。</dd></dl></div></section></div>${classroomLabPanel()}<section class="panel section-space"><div class="panel-head"><h2>可见操作记录</h2><small>追溯实际变更</small></div><div class="panel-body audit-list">${d.audit.length?d.audit.slice().reverse().slice(0,25).map(a=>`<div class="audit-row"><span>${date(a.created_at||a.date)}</span><strong>${esc(a.actor_name||a.actor_id||'演示操作人')}</strong><span>${esc(a.action||a.type)} · ${esc(a.entity_id||a.record_id||a.id)}</span></div>`).join(''):'<p class="tiny">当前身份暂无可见变更记录。</p>'}</div></section>`;}
function openModal(title,content,kicker='教师成长',drawer=false){state.returnFocus=document.activeElement;$('#overlay-root').innerHTML=`<div class="overlay-backdrop ${drawer?'drawer-backdrop':''}" data-backdrop><section class="modal ${drawer?'drawer':''}" role="dialog" aria-modal="true" aria-labelledby="dialogTitle"><header class="modal-head"><div><small>${esc(kicker)}</small><h2 id="dialogTitle">${esc(title)}</h2></div><button class="close-button" data-action="close" aria-label="关闭对话框">×</button></header><div class="modal-body">${content}</div></section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input:not([type=hidden]),.modal textarea,.modal select,.close-button')?.focus(),20);}
function closeModal(){const old=state.returnFocus;$('#overlay-root').innerHTML='';state.overlay=null;state.importPreview=null;document.body.style.overflow='';if(old?.isConnected)old.focus();}
function formFooter(text='保存记录'){return `<div class="form-status" role="alert"></div><div class="form-actions"><button class="button" type="button" data-action="close">取消</button><button class="button primary" type="submit">${esc(text)}</button></div>`;}
function textField(name,label,placeholder='',value='',required=true,type='text'){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?'required':''} ${type==='text'?'maxlength="500"':type==='number'?'min="0" step="0.1"':''}></label>`;}
function textarea(name,label,placeholder='',value='',required=true){return `<label>${esc(label)}<textarea name="${name}" placeholder="${esc(placeholder)}" maxlength="3000" ${required?'required':''}>${esc(value)}</textarea></label>`;}
function goalOptions(id,selected){return related('goals',id).map(g=>`<option value="${esc(g.id)}" ${g.id===selected?'selected':''}>${esc(g.title)}</option>`).join('');}
function evidenceChoices(id,selected=[],completeOnly=false){const ls=teacherLessons(id).filter(l=>num(l.first?.valid)>0&&(!completeOnly||l.first?.status!=='undetermined'));return ls.length?`<div class="checkbox-group">${ls.slice(0,20).map(l=>`<label class="checkbox-line"><input type="checkbox" name="evidence_ids" value="${esc(l.id)}" ${selected.includes(l.id)?'checked':''}><span>${date(l.date)} · ${esc(l.title)}<br><span class="tiny">${esc(l.class_name)} · ${esc(STATUS[l.first.status])}</span></span></label>`).join('')}</div>`:'<p class="field-help">当前没有可用课次依据，需先补齐数据再结案。</p>';}
function masteryPanel(value,label,retest=false){if(!value)return `<div class="mastery-panel retest"><div class="label">${label}</div><div class="big">—</div><p>尚无复测结果。首次结果保留原样，不以复测覆盖。</p></div>`;return `<div class="mastery-panel ${retest?'retest':''}"><div class="label">${label}${statusTag(value.status)}</div><div class="big">${rate(value.percentage)}</div><p>${esc(value.achieved||0)}人达标 / 应到${esc(value.expected||0)}人<br>有效${esc(value.valid||0)}人 · 未知${esc(value.unknown||0)}人</p></div>`;}
function showLesson(id){const l=state.data.lessons.find(x=>x.id===id);if(!l){toast('当前身份无法查看这节课的依据。',true);return;}const structure=l.analysis?.structure||[],total=structure.reduce((a,s)=>a+num(s.minutes),0)||1;const rows=l.first?.rows||[];const fb=state.data.feedback.filter(f=>f.lesson_id===id);const reflections=l.reflections||[];
openModal(l.title,`<div class="lesson-meta">${tag(lessonTeacherName(l))}${tag(l.class_name)}${tag(`${date(l.date)} · 第${l.sequence}课`)}${tag(l.lesson_type||'课堂示例')}</div><p class="lesson-context" style="margin-top:18px">${esc(l.context||'结合课堂任务、班级起点与任教时段理解本节表现。')}</p><div class="chips">${(l.learning_goals||[]).map(g=>tag(g)).join('')}</div><section class="lesson-section"><h3>首次作业与复测，分开记录</h3><div class="mastery-panels">${masteryPanel(l.first,'首次作业')}${masteryPanel(l.retest,'支持后的复测',true)}</div><p class="rule-note">以应到学生为范围，逐人核对90%正确率，再判断90%学生是否达标。资料不齐先标为待判断，精确阈值不使用四舍五入后的百分比。</p>${rows.length?`<details><summary class="text-link">展开逐人计数依据（${rows.length}人）</summary><div class="student-grid" style="margin-top:14px">${rows.map(r=>`<div class="student-chip ${r.status==='achieved'?'good':r.status==='not_achieved'?'bad':''}"><strong>${esc(r.label||r.student_id)}</strong>${esc(r.correct??'—')} / ${esc(r.total??'—')}题 · ${esc(STATUS[r.status]||r.status)}</div>`).join('')}</div></details>`:''}</section><section class="lesson-section"><h3>课堂结构与观察</h3><p>${esc(l.analysis?.summary||'当前尚无课堂分析说明。')}</p>${structure.length?`<div class="structure-bar" aria-label="课堂时间结构">${structure.map(s=>`<span style="width:${num(s.minutes)/total*100}%" title="${esc(s.label)} ${esc(s.minutes)}分钟"></span>`).join('')}</div><div class="structure-legend">${structure.map(s=>`<span>${esc(s.label)} ${esc(s.minutes)}分钟</span>`).join('')}</div>`:''}<div class="lesson-metrics">${(l.analysis?.metrics||[]).map(m=>`<div class="lesson-metric"><strong>${esc(m.value)}<small style="display:inline">${esc(m.unit||'')}</small></strong><span>${esc(m.label)}</span><small>${esc(m.note||'需结合课堂情境解释')}</small></div>`).join('')}</div><div class="chips">${(l.analysis?.issues||[]).map(x=>tag(`${x.label} · ${x.confirmed?'已人工核实':'待人工核实'}`,x.confirmed?'amber':'')).join('')}</div></section>${wiseDetails(l)}<section class="lesson-section"><div class="section-heading"><h3>课堂片段转写</h3>${tag('文字依据')}</div><p>以下仅为模拟转写，没有真实视频或录音。</p>${(l.analysis?.segments||[]).map(s=>`<details class="transcript"><summary>${esc(s.start)} — ${esc(s.end)} · ${esc(s.label)}</summary><p>${esc(s.transcript)}</p></details>`).join('')||'<p class="tiny">暂无片段转写。</p>'}${l.analysis?.original_report?`<details class="transcript"><summary>查看原始分析摘要</summary><p>${esc(typeof l.analysis.original_report==='string'?l.analysis.original_report:JSON.stringify(l.analysis.original_report))}</p></details>`:''}</section><section class="lesson-section"><div class="section-heading"><h3>我的课后反思与分享</h3>${own(l.teacher_id)?`<button class="text-link" data-action="reflect" data-id="${esc(id)}">写下我的反思 ↗</button>`:''}</div>${reflections.map(r=>`<div class="response"><strong>${date(r.created_at)} · ${r.share_with?.length?`已分享给${r.share_with.map(x=>({principal:'校长',mentor:'导师',group:'集团培养'}[x]||x)).join('、')}`:'本人私人草稿'}</strong>${esc(r.text)}</div>`).join('')||'<p>当前身份暂无可见反思。教师私人草稿不会自动成为正式评价。</p>'}</section>${fb.length?`<section class="lesson-section"><h3>正式课堂反馈</h3>${fb.map(f=>`<div class="feedback-item"><p>${esc(f.text)}</p><div class="feedback-meta">${esc(f.author_name)} · ${date(f.created_at)}</div>${(f.responses||[]).map(r=>`<div class="response"><strong>本人回应</strong>${esc(r.text)}</div>`).join('')}${own(l.teacher_id)?`<button class="text-link" data-action="respond-feedback" data-id="${esc(f.id)}">回应正式反馈 ↗</button>`:''}</div>`).join('')}</section>`:''}${sourceLine(l)}`,'每课依据 · 可追溯的课堂详情',true);}
function showAlert(id,advance=false){const a=state.data.alerts.find(x=>x.id===id);if(!a)return;const next=ALERT_STEPS[ALERT_STEPS.indexOf(a.status)+1];if(advance&&next&&principal()){openModal(`从“${STATUS[a.status]}”进入“${STATUS[next]}”`,`<div class="quiet-note">${esc(a.title)} · ${esc(teacherById(a.teacher_id)?.name)}<br>按核实、支持、复评的顺序跟进。结案需补充有效课次依据和复评说明。</div><form class="form-stack" data-form="alert" data-id="${esc(id)}"><input type="hidden" name="status" value="${next}">${textarea('note',next==='closed'?'复评结论与结案依据':'本次核实、支持或复评安排','具体做了什么、发现什么，以及下一次如何确认')}${textField('due_date','下次复查日期','','2026-11-13',true,'date')}<label>关联课堂记录${evidenceChoices(a.teacher_id,a.lesson_ids||[],next==='closed')}</label>${formFooter(next==='closed'?'保存结案记录':'保存跟进记录')}</form>`,'关注信号的逐步跟进');return;}openModal(a.title,`<p class="lesson-context">${esc(a.description)}</p>${alertSteps(a)}<dl class="facts" style="margin:23px 0"><dt>关联教师</dt><dd>${esc(teacherById(a.teacher_id)?.name)}</dd><dt>跟进责任</dt><dd>${esc(a.owner_name||'待明确')}</dd><dt>复查日期</dt><dd>${date(a.due_date)}</dd></dl><h3 style="margin:20px 0 15px">过程记录</h3>${timeline((a.history||[]).map(h=>({date:h.date||h.created_at,title:STATUS[h.status]||h.status,detail:h.note})))}<div class="action-row">${(a.lesson_ids||[]).map(id=>`<button class="button small" data-lesson="${esc(id)}">查看${esc(state.data.lessons.find(l=>l.id===id)?.title||id)} ${arrow}</button>`).join('')}</div>${principal()&&a.status!=='closed'?`<div class="form-actions"><button class="button primary" data-action="advance-alert" data-id="${esc(id)}">记录下一步：${esc(STATUS[next])}</button></div>`:''}`,'信号先核实，之后安排支持');}
function showGoalForm(){const t=teacher();if(!t||!canGoal(t.id))return;openModal('共同确定一个发展目标',`<div class="quiet-note">${esc(t.name)} · 每个短周期聚焦一至两个目标。明确起点、预期变化与复评时间。</div><form class="form-stack" data-form="goal" data-teacher-id="${esc(t.id)}">${textField('title','本期发展目标','例如：让提问后更多学生说出解题思路')}${textarea('baseline','当前起点与依据','描述当前可观察到的课堂或育人表现')}${textarea('target','希望看到的变化','写清实践任务和复评时要看什么')}${textField('due_date','约定复评日期','','2026-11-27',true,'date')}${formFooter('保存发展目标')}</form>`,'目标由教师与校长共同确认');}
function showSupportForm(teacherId,goalId){const t=teacherById(teacherId)||teacher();if(!t||!principal())return;const goals=related('goals',t.id);if(!goals.length){toast('先为这位教师共同确定一个发展目标。',true);return;}const owners=state.data.actors.filter(a=>a.role!=='group'&&(a.role!=='principal'||a.id===state.actor)&&(!a.id.startsWith('teacher-')||a.id===t.id));openModal('安排一项具体支持',`<div class="quiet-note">${esc(t.name)} · 支持需要有人负责、有完成时间，并留下实际落实的依据。</div><form class="form-stack" data-form="support" data-teacher-id="${esc(t.id)}"><label>关联发展目标<select name="goal_id" required>${goalOptions(t.id,goalId)}</select></label>${textField('title','学校或导师提供什么支持','例如：每周安排一次同课共备和课堂观察')}<label>支持责任人<select name="owner_id" required>${owners.map(a=>`<option value="${esc(a.id)}" ${a.id===state.actor?'selected':''}>${esc(a.name)} · ${ROLE[a.role]||a.role}</option>`).join('')}</select></label>${textField('due_date','计划落实日期','','2026-11-13',true,'date')}${formFooter('保存支持安排')}</form>`,'把培养承诺变成可兑现的安排');}
function showCompleteSupport(id){const s=state.data.supports.find(x=>x.id===id);if(!s)return;openModal('记录支持已落实',`<div class="quiet-note">${esc(s.title)}<br>${esc(teacherById(s.teacher_id)?.name)} · ${esc(s.owner_name)}</div><form class="form-stack" data-form="complete-support" data-id="${esc(id)}">${textarea('evidence','实际提供的支持与核验依据','记录时间、参与人、实际行动以及可回看的材料位置')}${formFooter('确认支持已落实')}</form>`,'以实际行动兑现培养承诺');}
function showReview(id){const g=state.data.goals.find(x=>x.id===id);if(!g)return;openModal('记录目标的阶段复评',`<div class="quiet-note">${esc(g.title)}<br>预期变化：${esc(g.target)}</div><form class="form-stack" data-form="review" data-id="${esc(g.id)}" data-teacher-id="${esc(g.teacher_id)}"><label>当前结论<select name="conclusion" required>${['partial','achieved','not_achieved','undetermined'].map(s=>`<option value="${s}">${STATUS[s]}</option>`).join('')}</select></label>${textarea('text','观察到的变化、支持落实与下一步','把教师的实践变化和组织提供的支持一起说明；资料待补齐可保留待判断')}<label>本次复评关联的课堂记录${evidenceChoices(g.teacher_id)}</label><p class="field-help">保存后形成正式反馈，保留原文并允许教师本人回应。</p>${formFooter('保存复评与正式反馈')}</form>`,'复评需要回到起点与依据');}
function showResponse(id){const f=state.data.feedback.find(x=>x.id===id);if(!f)return;openModal('回应正式反馈',`<div class="quiet-note">${esc(f.text)}</div><form class="form-stack" data-form="response" data-id="${esc(id)}">${textarea('text','本人解释、补充事实或支持需要','可以说明不同意见、补充依据，并提出下一步需要的支持')}<p class="field-help">作出回应表示你已反馈，不等同于认可原评价。原反馈与本人回应分别保留。</p>${formFooter('保存本人回应')}</form>`,'教师有权补充与表达不同意见');}
function showMentorship(){const t=teacher();if(!t||!principal())return;const goals=related('goals',t.id);if(!goals.length){toast('请先共同确定教师的发展目标。',true);return;}const mentors=state.data.mentors||[];openModal('为具体目标安排同伴结对',`<div class="quiet-note">${esc(t.name)} · 结合导师专长、意愿和当前容量。只有双方意愿均已确认后才能建立关系。</div><form class="form-stack" data-form="mentorship" data-teacher-id="${esc(t.id)}"><label>关联发展目标<select name="goal_id" required>${goalOptions(t.id)}</select></label><label>选择导师<select name="mentor_id" id="mentorChoice" required><option value="">请选择有意愿及容量的导师</option>${mentors.map(m=>`<option value="${esc(m.id)}" ${!m.willing||num(m.active_count)>=num(m.capacity)?'disabled':''}>${esc(m.name)} · ${esc(m.subject)} · ${esc((m.strengths||[]).join('、'))}（${m.active_count}/${m.capacity}）</option>`).join('')}</select></label>${textarea('reason','为什么适合这次结对','说明目标、导师专长及预计共同实践的安排')}${textField('end_date','结对结束与复盘日期','','2026-12-25',true,'date')}<div class="checkbox-group"><label class="checkbox-line"><input type="checkbox" name="teacher_consent" required><span>已与教师本人沟通，教师愿意参与本次结对。</span></label><label class="checkbox-line"><input type="checkbox" name="mentor_consent" required><span>已与导师沟通，导师愿意承担约定的辅导安排。</span></label></div>${formFooter('确认双方意愿并建立结对')}</form>`,'双向选择 · 明确周期 · 尊重容量');}
function showMentorNote(id){const m=state.data.mentorships.find(x=>x.id===id);if(!m)return;openModal('记录一次辅导与实践',`<div class="quiet-note">${esc(teacherById(m.teacher_id)?.name)} ⇄ ${esc(m.mentor_name)}<br>${esc(m.reason)}</div><form class="form-stack" data-form="mentor-note" data-id="${esc(id)}">${textarea('text','本次做了什么，下一次准备怎样尝试','描述共备、观察、反馈或实践变化，以及下一步安排')}${formFooter('保存辅导记录')}</form>`,'同伴支持回到真实实践');}
function showReflection(id){const l=state.data.lessons.find(x=>x.id===id);if(!l||!own(l.teacher_id))return;openModal('写下我的课后反思',`<div class="quiet-note">${esc(l.title)} · ${date(l.date)}<br>默认仅本人可见，你可以分别选择分享对象。</div><form class="form-stack" data-form="reflection" data-id="${esc(id)}">${textarea('text','我的观察、尝试与需要的支持','哪些环节有效？哪里遇到困难？下一节课想怎样调整？')}<div class="checkbox-group"><label class="checkbox-line"><input type="checkbox" name="share_with" value="principal"><span>分享给本校校长</span></label><label class="checkbox-line"><input type="checkbox" name="share_with" value="mentor"><span>分享给当前结对导师</span></label><label class="checkbox-line"><input type="checkbox" name="share_with" value="group"><span>分享给集团授权培养角色</span></label></div><p class="field-help">不勾选即保存为本人私人草稿，不自动转为正式评价材料。</p>${formFooter('保存我的反思')}</form>`,'本人草稿自主分享');}
function showAspiration(){const t=teacher();if(!t||!own(t.id))return;openModal('更新我的发展方向',`<form class="form-stack" data-form="aspiration" data-id="${esc(t.id)}">${textarea('aspiration','我希望成为怎样的教师','教学、育人、教研、导师或管理，都可以是发展路径。',t.aspiration)}${formFooter('保存我的发展方向')}</form>`,'发展方向尊重本人意愿');}
async function downloadTemplate(){try{const r=await fetch(`${API}/templates/homework.csv`,{headers:{'X-Demo-Actor':state.actor}});if(!r.ok)throw new Error('模板暂时无法下载，请检查本地服务。');const text=await r.text(),url=URL.createObjectURL(new Blob(['\ufeff',text],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='厚外大教研与人才发展-作业导入模板.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('CSV模板已下载。');}catch(e){toast(e.message,true);}}
async function showImport(){if(!principal())return;state.importPreview=null;openModal('导入作业样本',`<div class="quiet-note">仅允许既有课次和SIM学生。先预览改动，再确认写入；本流程不会连接真实供应商系统。</div><form class="form-stack" data-form="import-preview"><label>CSV内容<textarea name="csv" class="code" rows="8" required spellcheck="false" placeholder="lesson_id,student_id,attempt,correct,total,status"></textarea></label><label class="text-link" style="display:block">从本地CSV读取<input type="file" id="csvFile" accept=".csv,text/csv" style="font-size:10px"></label><div class="form-status" role="alert"></div><div class="form-actions"><button class="button" type="button" data-action="download-template">下载模板</button><button class="button primary" type="submit">校验并预览</button></div></form><div id="importPreview"></div>`,'文件交换 · 两步确认');try{const r=await fetch(`${API}/templates/homework.csv`,{headers:{'X-Demo-Actor':state.actor}});if(!r.ok)throw new Error('请下载模板后粘贴CSV内容。');const text=await r.text();if($('[data-form="import-preview"] textarea'))$('[data-form="import-preview"] textarea').value=text;}catch(e){toast(e.message,true);}}
function renderImportPreview(p){const summary=p.summary||{},changes=p.changes||[];$('#importPreview').innerHTML=`<div class="section-heading section-space"><h3>预览校验通过</h3>${tag('尚未写入','amber')}</div><div class="import-summary"><span>输入 ${esc(summary.rows??p.rows?.length??0)}行</span><span>将修改 ${esc(summary.changed??changes.length)}项</span><span>无变化 ${esc(summary.unchanged??0)}项</span></div>${p.warnings?.length?`<div class="quiet-note">${p.warnings.map(esc).join('<br>')}</div>`:''}<div class="preview-wrap"><pre>${esc(changes.length?JSON.stringify(changes,null,2):'该文件内容与当前记录相同，没有需要修改的项目。')}</pre></div><p class="field-help">确认时会重新检查当前身份、课次和预览版本。同一批次重复确认保持幂等。</p><div class="form-actions"><button class="button" data-action="close">取消</button><button class="button primary" data-action="confirm-import">确认写入样本</button></div>`;}
async function saveForm(form){const f=new FormData(form),v=Object.fromEntries(f.entries()),kind=form.dataset.form;const teacherId=form.dataset.teacherId;let path,body,success='记录已保存。';switch(kind){case 'goal':path='/goals';body={teacher_id:teacherId,title:v.title,baseline:v.baseline,target:v.target,due_date:v.due_date};success='发展目标已保存，后续支持与复评可持续跟进。';break;case 'support':path='/supports';body={teacher_id:teacherId,goal_id:v.goal_id,title:v.title,owner_id:v.owner_id,due_date:v.due_date};success='支持安排已保存。';break;case 'complete-support':path=`/supports/${form.dataset.id}/complete`;body={evidence:v.evidence};success='支持已记录为落实，核验依据已保留。';break;case 'review':path='/reviews';body={teacher_id:teacherId,goal_id:form.dataset.id,conclusion:v.conclusion,text:v.text,evidence_ids:f.getAll('evidence_ids')};success='复评和正式反馈已保存，教师本人可以回应。';break;case 'response':path=`/feedback/${form.dataset.id}/responses`;body={text:v.text};success='本人回应已保存，原反馈保留。';break;case 'mentorship':path='/mentorships';body={teacher_id:teacherId,mentor_id:v.mentor_id,goal_id:v.goal_id,end_date:v.end_date,reason:v.reason,teacher_consent:f.has('teacher_consent'),mentor_consent:f.has('mentor_consent')};success='结对关系已建立，双方意愿与周期已记录。';break;case 'mentor-note':path=`/mentorships/${form.dataset.id}/notes`;body={text:v.text};success='辅导与实践记录已保存。';break;case 'reflection':path='/reflections';body={lesson_id:form.dataset.id,text:v.text,share_with:f.getAll('share_with')};success=body.share_with.length?'反思已保存并按所选范围分享。':'反思已保存为本人私人草稿。';break;case 'aspiration':path=`/profiles/${form.dataset.id}`;body={aspiration:v.aspiration};success='我的发展方向已更新。';break;case 'alert':if(v.status==='closed'&&!f.getAll('evidence_ids').length)throw new Error('结案请至少选择一条本教师的有效课次依据，并写明复评结论。');path=`/alerts/${form.dataset.id}/actions`;body={status:v.status,note:v.note,due_date:v.due_date,evidence_ids:f.getAll('evidence_ids')};success='跟进状态已更新，过程记录已保留。';break;case 'trial':path='/classroom-trials';body={lesson_id:v.lesson_id,checks:Object.fromEntries((state.lab.checks||[]).map(c=>[c.key,v['check_'+c.key]])),decision:v.decision,notes:v.notes,report_minutes:v.report_minutes===''?null:Number(v.report_minutes),review_minutes:v.review_minutes===''?null:Number(v.review_minutes)};success='课堂分析试验核验记录已保存。';break;case 'import-preview':{const p=await post('/imports/preview',{csv:v.csv});state.importPreview=p;renderImportPreview(p);toast('预览校验通过，确认后才会写入。');return;}default:throw new Error('无法识别该记录表单。');}await post(path,body);closeModal();await refresh();toast(success);}
async function action(name,el){switch(name){case 'menu':state.mobileNav=!state.mobileNav;render();break;case 'close':closeModal();break;case 'nav':go(el.dataset.pageTarget);break;case 'teacher-lessons':state.lessonTeacher=el.dataset.id;go('lessons');break;case 'add-goal':showGoalForm();break;case 'add-support':showSupportForm(el.dataset.teacherId,el.dataset.goalId);break;case 'complete-support':showCompleteSupport(el.dataset.id);break;case 'review-goal':showReview(el.dataset.id);break;case 'respond-feedback':showResponse(el.dataset.id);break;case 'add-mentorship':showMentorship();break;case 'mentor-note':showMentorNote(el.dataset.id);break;case 'reflect':showReflection(el.dataset.id);break;case 'edit-aspiration':showAspiration();break;case 'alert-detail':showAlert(el.dataset.id);break;case 'advance-alert':showAlert(el.dataset.id,true);break;case 'download-template':await downloadTemplate();break;case 'record-trial':showTrialForm(el.dataset.id);break;case 'retry-lab':state.labActor=null;await loadLab();break;case 'goal-from-lesson':state.teacher=el.dataset.teacherId;showGoalForm();break;case 'import':await showImport();break;case 'retry-report':state.reportKey='';await loadReport();break;case 'view-archive':{try{const result=await request(`/reports/${encodeURIComponent(el.dataset.teacherId)}/archives/${encodeURIComponent(el.dataset.id)}`);const t=teacherById(result.teacher_id)||teacher();openModal('已归档的阶段报告',`<div class="quiet-note">归档时间 ${date(result.created_at)} · 原版快照 ${esc(result.id)}<br>以下是归档时的报告内容，与当前实时报告分别保留。</div>${reportDetail(result.snapshot,t,true)}`,'历史报告原版',true);}catch(e){toast(e.message,true);}break;}case 'archive-report':{const t=teacher();if(!t)return;el.disabled=true;try{await post(`/reports/${t.id}/archive`,{period:state.period});state.reportKey='';await loadReport();toast('本期报告快照已归档。');}catch(e){toast(e.message,true);el.disabled=false;}break;}case 'confirm-import':{if(!state.importPreview?.preview_id){toast('请先校验并预览CSV内容。',true);return;}el.disabled=true;try{const result=await post('/imports/confirm',{preview_id:state.importPreview.preview_id});closeModal();await refresh();toast(result.repeated?'该批次已确认过，没有重复写入。':'作业样本已写入，达标结果已重新计算。');}catch(e){toast(e.message,true);el.disabled=false;}break;}}}
document.addEventListener('click',async e=>{const page=e.target.closest('[data-page]');if(page){state.mobileNav=false;go(page.dataset.page);return;}const t=e.target.closest('[data-teacher]');if(t){state.profileTab='growth';go('profile',t.dataset.teacher);return;}const select=e.target.closest('[data-select-teacher]');if(select){state.teacher=select.dataset.selectTeacher;go('profile',state.teacher);return;}const tab=e.target.closest('[data-profile-tab]');if(tab){state.profileTab=tab.dataset.profileTab;render();return;}const lesson=e.target.closest('[data-lesson]');if(lesson){showLesson(lesson.dataset.lesson);return;}const period=e.target.closest('[data-period]');if(period){state.period=period.dataset.period;state.report=null;await loadReport();return;}const a=e.target.closest('[data-action]');if(a){try{await action(a.dataset.action,a);}catch(err){toast(err.message,true);}return;}if(e.target.matches('[data-backdrop]'))closeModal();if(state.mobileNav&&!e.target.closest('.sidebar')&&!e.target.closest('.mobile-menu')){state.mobileNav=false;render();}});
document.addEventListener('change',async e=>{const id=e.target.id;if(id==='actorSelect'){closeModal();state.actor=e.target.value;sessionStorage.setItem('houwai-teacher-actor',state.actor);state.teacher=null;state.report=null;state.search='';state.subject='all';state.scenario='all';state.lessonTeacher='all';try{await refresh();toast('已切换演示身份，授权数据由本地服务重新返回。');}catch(err){showError(err);}return;}if(['subjectFilter','scenarioFilter'].includes(id)){state[id==='subjectFilter'?'subject':'scenario']=e.target.value;render();return;}if(['supportTeacher','reportTeacher'].includes(id)){state.teacher=e.target.value;if(id==='reportTeacher'){state.report=null;await loadReport();}else render();return;}if(id==='lessonTeacherFilter'){state.lessonTeacher=e.target.value;render();return;}if(id==='lessonStatusFilter'){state.lessonStatus=e.target.value;render();return;}if(id==='csvFile'&&e.target.files?.[0]){try{const file=e.target.files[0];if(file.size>1024*1024)throw new Error('演示CSV请保持在1MB以内。');const text=await file.text();$('[data-form="import-preview"] textarea').value=text;state.importPreview=null;$('#importPreview').innerHTML='';}catch(err){toast(err.message,true);}}});
document.addEventListener('input',e=>{if(e.target.id==='teacherSearch'){const start=e.target.selectionStart;state.search=e.target.value;render();const input=$('#teacherSearch');input.focus();input.setSelectionRange(start,start);}if(e.target.name==='csv'){state.importPreview=null;if($('#importPreview'))$('#importPreview').innerHTML='';}});
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const submit=$('[type=submit]',form),status=$('.form-status',form);if(status)status.textContent='';if(submit)submit.disabled=true;try{await saveForm(form);}catch(err){if(status&&status.isConnected)status.textContent=`${err.message}${err.details?`\n${typeof err.details==='string'?err.details:JSON.stringify(err.details)}`:''}`;toast(err.message,true);}finally{if(submit?.isConnected)submit.disabled=false;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('.modal'))closeModal();else if(state.mobileNav){state.mobileNav=false;render();}}if(e.key==='Tab'&&$('.modal')){const items=$$('button:not(:disabled),a[href],input:not([type=hidden]),textarea,select,[tabindex="0"]',$('.modal')).filter(x=>x.offsetParent!==null);if(items.length){const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}}});
window.addEventListener('hashchange',()=>{if(!state.data)return;readRoute();state.mobileNav=false;render();if(state.page==='reports')loadReport();window.scrollTo({top:0});});
function showError(error){$('#app').innerHTML=`<main><div class="error-panel"><div class="eyebrow">厚外大教研与人才发展 · 本地服务</div><h1>暂时无法读取成长档案</h1><p>${esc(error.message)}<br>请确认本地演示服务已经启动，再重新载入。页面没有使用备用假数据。</p><button class="button primary" id="retryBootstrap">重新读取</button></div></main>`;$('#retryBootstrap').addEventListener('click',()=>refresh().catch(showError));}
// organization.js owns the scoped initial load after all workflow tools are ready.

function classroomComparison(r,archived=false){const list=r.classroom_comparison||[];if(!list.length)return '<div class="quiet-note">当前周期课堂行为的前后对照仍待补充，先回到单课观察与片段依据。</div>';const value=(v,u)=>v==null?'—':`${Number(v).toFixed(Number(v)%1?1:0)}${esc(u||'')}`;return `<div class="section-heading"><h2>课堂实践，有什么变化</h2><span class="tiny">前期 → 本期</span></div><div class="classroom-comparison">${list.map(m=>`<article class="comparison-item"><h3>${esc(m.label)}</h3><div class="comparison-values"><div><small>前期 · ${esc(m.previous_n||0)}节观察</small><strong>${value(m.previous,m.unit)}</strong></div><span>→</span><div><small>本期 · ${esc(m.current_n||0)}节观察</small><strong>${value(m.current,m.unit)}</strong></div></div><p>${esc(m.note||'结合课型与课堂目标解释变化，不将数值高低直接认定为教学好坏。')}</p><div class="action-row">${(archived?[]:(m.evidence_ids||[])).slice(-2).map(id=>`<button class="text-link" data-lesson="${esc(id)}">回看课堂记录 ↗</button>`).join('')}</div></article>`).join('')}</div>`;}
function retestComparison(r,archived=false){const snapshot=r.retest_summary;if(archived&&!snapshot)return '<div class="quiet-note">此归档原版未保存独立复测摘要，不用当前作业数据重新计算。首次结果与阶段观察保留归档时内容。</div>';const records=snapshot?[]:state.data.lessons.filter(l=>l.teacher_id===r.teacher_id&&l.date>=r.start&&l.date<=r.end&&l.retest),valid=records.filter(l=>l.retest.status!=='undetermined'),after=valid.filter(l=>l.retest.status==='achieved'),count=snapshot?.lessons??records.length,validCount=snapshot?.valid_lessons??valid.length,achievedCount=snapshot?.achieved_lessons??after.length,ids=snapshot?.lesson_ids||records.map(l=>l.id);return `<div class="retest-summary"><div>${icon('undo')}<div><h3>同课复测，观察支持后的变化</h3><p>本期${count}节课有复测，${validCount}节资料完整，其中${achievedCount}节复测达标。首次结果独立保留。</p></div></div>${!archived&&ids.length?`<button class="text-link" data-lesson="${esc(ids[ids.length-1])}">对照首次与复测 ↗</button>`:`<span class="tiny">${archived?'归档摘要': '暂无复测记录'}</span>`}</div>`;}

function wiseDetails(l){const a=l.analysis||{},wise=a.wise||[],chain=a.question_chain||[],points=a.knowledge_points||[],suggestions=a.suggestions||[];if(!wise.length&&!chain.length&&!suggestions.length)return '';return `<section class="lesson-section"><div class="section-heading"><h3>从四个观察面，理解这节课</h3>${tag('分析示例 · 待人工核验','amber')}</div><div class="wise-grid">${wise.map((w,i)=>`<article class="wise-item"><small>0${i+1}</small><h4>${esc(w.dimension)}</h4><p>${esc(w.summary)}</p><span>${w.evidence_ids?.length||0}条片段依据</span></article>`).join('')}</div>${points.length?`<div class="chips" style="margin-top:15px">${points.map(p=>tag(typeof p==='object'?p.name||p.label: p)).join('')}</div>`:''}<p class="rule-note">参考2026.07供应商材料中的WISE思路组织观察。当前分析来自本地样本，并非讯飞或自研模型的实际输出。</p></section><section class="lesson-section"><h3>问题链与思维过程</h3>${chain.map((q,i)=>`<article class="question-chain"><span class="question-number">${i+1}</span><div><h4>${esc(q.question)}</h4><p>继续追问：${esc(q.followup||'待结合课题补充')}</p><small>${esc(q.thinking_level||'思维要求待核实')} · ${esc(q.evidence_id||'片段依据待补充')}</small></div></article>`).join('')||'<p>问题链仍待补充。</p>'}<h3 style="margin:24px 0 12px">下一次实践可以尝试</h3><ul class="observation-list">${suggestions.map(v=>`<li>${esc(typeof v==='object'?v.text||v.title||v.action||JSON.stringify(v):v)}</li>`).join('')}</ul>${canGoal(l.teacher_id)?`<div class="action-row"><button class="text-link" data-action="goal-from-lesson" data-teacher-id="${esc(l.teacher_id)}">与教师共同转为发展目标 ↗</button></div>`:''}<p class="field-help">建议需由教师与校长确认，不能直接成为正式评价或人事结论。</p></section>`;}
function classroomLabPanel(){return `<section class="section-space"><div class="section-heading"><h2>课堂分析试验室</h2>${principal()?'<button class="text-link" data-action="record-trial">记录一次核验 ↗</button>':tag('授权查看','blue')}</div><div id="classroomLabContent">${state.labLoading?'<div class="panel loading">正在读取试验能力与核验记录…</div>':state.labError?`<div class="panel"><div class="panel-body"><p class="tiny">${esc(state.labError)}</p><div class="action-row"><button class="text-link" data-action="retry-lab">重新读取课堂试验区 ↗</button></div></div></div>`:state.lab?labContents(state.lab):'<div class="panel loading">正在核对课堂分析能力…</div>'}</div></section>`;}
async function loadLab(){const requestedActor=state.actor;state.labActor=state.actor;state.labLoading=true;state.labError='';try{const result=await request('/classroom-lab');if(state.actor!==requestedActor||state.labActor!==requestedActor)return;state.lab=result;state.labLoading=false;if(state.page==='sources'&&$('#classroomLabContent'))$('#classroomLabContent').innerHTML=labContents(result);}catch(e){if(state.actor!==requestedActor||state.labActor!==requestedActor)return;state.labLoading=false;state.labError=e.message;if(state.page==='sources'&&$('#classroomLabContent'))$('#classroomLabContent').innerHTML=`<div class="panel"><div class="panel-body"><p class="tiny">课堂试验区暂未读取：${esc(e.message)}</p><div class="action-row"><button class="text-link" data-action="retry-lab">重新读取 ↗</button></div></div></div>`;}}
function labContents(lab){const reference=lab.reference||{};return `<div class="lab-reference"><div>${icon('book')}<div><h3>${esc(reference.title||'AI课堂实录与分析 · 2026.07供应商材料')}</h3><p>${esc(reference.note||'供应商材料作为能力参照，需在本校课程上实际核验。')}</p></div></div>${tag(`${reference.pages||41}页产品参考`)}</div><div class="provider-grid">${(lab.providers||[]).map(p=>`<article class="provider-item"><div>${tag(p.id==='synthetic'?'当前样本':p.id==='iflytek'?'待实际试验':'未来规划',p.id==='synthetic'?'green':'amber')}</div><h3>${esc(p.name)}</h3><p>${esc(p.description)}</p></article>`).join('')}</div><section class="panel section-space"><div class="panel-head"><h2>要验证的能力</h2><small>材料声明与校内实测分开记录</small></div><div class="panel-body"><div class="capability-grid">${(lab.capabilities||[]).map(c=>`<article><h3>${esc(c.title)}</h3><p>${esc(c.description)}</p><small>参考 ${Array.isArray(c.reference_pages)?c.reference_pages.map(p=>'P'+p).join('、'):esc(c.reference_pages||'供应商材料')} · 待实测</small></article>`).join('')}</div><div class="quiet-note">供应商材料包含教师阶段报告能力（P26），实际字段、历史数据及接口开放范围仍待核验。当前页面报告由本地演示数据生成。</div></div></section><section class="panel section-space"><div class="panel-head"><h2>试验核验记录</h2>${principal()?button('填写核验表','record-trial','',false,'check'):tag('授权只读','blue')}</div><div class="panel-body">${(lab.trials||[]).map(t=>`<article class="trial-record"><div class="goal-heading"><h3>${esc(state.data.lessons.find(l=>l.id===t.lesson_id)?.title||t.lesson_id)}</h3>${tag({continue:'继续验证',adjust:'调整后再试',hold:'暂缓'}[t.decision]||t.decision,t.decision==='continue'?'green':'amber')}</div><p>${esc(t.notes)}</p><div class="chips">${Object.entries(t.checks||{}).map(([key,status])=>tag(`${lab.checks.find(c=>c.key===key)?.label||key}：${{pending:'待核验',pass:'通过',review:'需复核',fail:'未通过'}[status]||status}`,status==='pass'?'green':status==='fail'?'red':'')).join('')}</div><small>核验人 ${esc(t.reviewer_name)} · ${date(t.created_at)}<br>生成报告：${t.report_minutes==null?'未实测':esc(t.report_minutes)+'分钟'} · 人工核验：${t.review_minutes==null?'未实测':esc(t.review_minutes)+'分钟'}</small></article>`).join('')||empty('尚未保存课堂试验核验','选取一节授权课次，逐项记录转写、片段、结论和建议是否可信。')}</div></section><section class="panel section-space"><div class="panel-head"><h2>从采购试验到自主建设</h2><small>依据真实验证结果决定</small></div><div class="panel-body"><div class="lab-roadmap">${(lab.roadmap||[]).map((r,i)=>`<article><span>0${i+1}</span><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p></article>`).join('')}</div><p class="field-help" style="margin-top:18px">${esc(lab.notice||'当前运行的是本地流程，未连接供应商服务或自研分析模型。')}</p></div></section>`;}
function showTrialForm(lessonId){if(!principal())return;if(!state.lab){toast('请先载入数据与接入页面的课堂试验区。',true);go('sources');return;}if(!state.data.lessons.length){toast('当前校区没有可用于试验的授权课次。',true);return;}openModal('核验一份课堂分析结果',`<div class="quiet-note">当前核验对象为本地样例。逐项保留核验结果，报告与人工检查耗时未实测时保持空白。</div><form class="form-stack" data-form="trial"><label>选取课堂样例<select name="lesson_id" required>${state.data.lessons.map(l=>`<option value="${esc(l.id)}" ${l.id===lessonId?'selected':''}>${esc(lessonTeacherName(l))} · ${date(l.date)} · ${esc(l.title)}</option>`).join('')}</select></label><div class="trial-checks">${(state.lab.checks||[]).map(c=>`<label><span>${esc(c.label)}<small>${esc(c.description)}</small></span><select name="check_${esc(c.key)}" required><option value="pending">待核验</option><option value="pass">通过</option><option value="review">需复核</option><option value="fail">未通过</option></select></label>`).join('')}</div><div class="form-grid">${textField('report_minutes','报告生成耗时（分钟）','未实测请留空','',false,'number')}${textField('review_minutes','人工核验耗时（分钟）','未实测请留空','',false,'number')}</div><label>下一步试验决定<select name="decision" required><option value="adjust">调整后再试</option><option value="continue">继续验证</option><option value="hold">暂缓</option></select></label>${textarea('notes','核验依据、问题与下次安排','说明片段是否对得上，分析结论有何依据，建议对教学有没有帮助')}<p class="field-help">有“未通过”项目时不能选择继续验证。供应商销售材料中的时效不作为本校实测耗时。</p>${formFooter('保存课堂试验核验')}</form>`,'供应商能力参照 · 校内样例验证');}
